com.mirth.connect.plugins.javascriptstep.script:
/*
 * ORU_R01_IN
 * Source Transformer
 *
 * Extract important transaction, patient, order,
 * and observation values from the inbound ORU^R01.
 *
 * These values become the operational context used
 * by validation, audit persistence, ACK policy,
 * quarantine handling, and later FHIR reconciliation.
 */


/* ---------------------------------------------------------
 * MESSAGE / TRANSACTION
 * --------------------------------------------------------- */

var messageControlId =
    String(msg['MSH']['MSH.10']['MSH.10.1']);

var messageType =
    String(msg['MSH']['MSH.9']['MSH.9.1']);

var triggerEvent =
    String(msg['MSH']['MSH.9']['MSH.9.2']);

var messageStructure =
    String(msg['MSH']['MSH.9']['MSH.9.3']);

var sendingApplication =
    String(msg['MSH']['MSH.3']['MSH.3.1']);

var sendingFacility =
    String(msg['MSH']['MSH.4']['MSH.4.1']);


/* ---------------------------------------------------------
 * PATIENT IDENTITY
 * --------------------------------------------------------- */

var patientIdentifier =
    String(msg['PID']['PID.3']['PID.3.1']);

var assigningAuthority =
    String(msg['PID']['PID.3']['PID.3.4']);

var identifierType =
    String(msg['PID']['PID.3']['PID.3.5']);


/* ---------------------------------------------------------
 * ORDER / REPORT
 * --------------------------------------------------------- */

var placerOrderNumber =
    String(msg['OBR']['OBR.2']['OBR.2.1']);

var fillerOrderNumber =
    String(msg['OBR']['OBR.3']['OBR.3.1']);

var serviceCode =
    String(msg['OBR']['OBR.4']['OBR.4.1']);

var serviceText =
    String(msg['OBR']['OBR.4']['OBR.4.2']);

var serviceCodingSystem =
    String(msg['OBR']['OBR.4']['OBR.4.3']);

var obrResultStatus =
    String(msg['OBR']['OBR.25']['OBR.25.1']);


/* ---------------------------------------------------------
 * OBSERVATION
 * --------------------------------------------------------- */

var obxValueType =
    String(msg['OBX']['OBX.2']['OBX.2.1']);

var observationCode =
    String(msg['OBX']['OBX.3']['OBX.3.1']);

var observationText =
    String(msg['OBX']['OBX.3']['OBX.3.2']);

var observationCodingSystem =
    String(msg['OBX']['OBX.3']['OBX.3.3']);

var observationValue =
    String(msg['OBX']['OBX.5']['OBX.5.1']);

var units =
    String(msg['OBX']['OBX.6']['OBX.6.1']);

var referenceRange =
    String(msg['OBX']['OBX.7']['OBX.7.1']);

var abnormalFlag =
    String(msg['OBX']['OBX.8']['OBX.8.1']);

var obxResultStatus =
    String(msg['OBX']['OBX.11']['OBX.11.1']);


/* ---------------------------------------------------------
 * PUBLISH OPERATIONAL CONTEXT
 * --------------------------------------------------------- */

channelMap.put(
    "oru_message_control_id",
    messageControlId
);

channelMap.put(
    "oru_message_type",
    messageType
);

channelMap.put(
    "oru_trigger_event",
    triggerEvent
);

channelMap.put(
    "oru_message_structure",
    messageStructure
);

channelMap.put(
    "oru_sending_application",
    sendingApplication
);

channelMap.put(
    "oru_sending_facility",
    sendingFacility
);

channelMap.put(
    "oru_patient_identifier",
    patientIdentifier
);

channelMap.put(
    "oru_assigning_authority",
    assigningAuthority
);

channelMap.put(
    "oru_identifier_type",
    identifierType
);

channelMap.put(
    "oru_placer_order_number",
    placerOrderNumber
);

channelMap.put(
    "oru_filler_order_number",
    fillerOrderNumber
);

channelMap.put(
    "oru_service_code",
    serviceCode
);

channelMap.put(
    "oru_service_text",
    serviceText
);

channelMap.put(
    "oru_service_coding_system",
    serviceCodingSystem
);

channelMap.put(
    "oru_obr_status",
    obrResultStatus
);

channelMap.put(
    "oru_obx_value_type",
    obxValueType
);

channelMap.put(
    "oru_observation_code",
    observationCode
);

channelMap.put(
    "oru_observation_text",
    observationText
);

channelMap.put(
    "oru_observation_coding_system",
    observationCodingSystem
);

channelMap.put(
    "oru_observation_value",
    observationValue
);

channelMap.put(
    "oru_units",
    units
);

channelMap.put(
    "oru_reference_range",
    referenceRange
);

channelMap.put(
    "oru_abnormal_flag",
    abnormalFlag
);

channelMap.put(
    "oru_obx_status",
    obxResultStatus
);


/* ---------------------------------------------------------
 * OPERATOR TRACE
 * --------------------------------------------------------- */

logger.info(
    "ORU result context: " +
    "control_id=" + messageControlId +
    ", patient_id=" + patientIdentifier +
    ", placer_order=" + placerOrderNumber +
    ", filler_order=" + fillerOrderNumber +
    ", observation=" + observationCode +
    ", value=" + observationValue +
    ", units=" + units +
    ", abnormal_flag=" + abnormalFlag +
    ", obr_status=" + obrResultStatus +
    ", obx_status=" + obxResultStatus
);

/*
 * ORU_R01_IN semantic validation.
 *
 * This validates the current simplified ORU profile:
 * one OBR, one OBX, numeric glucose-style result.
 */

var failures = [];

function valueOf(name) {
    var value = channelMap.get(name);

    if (value == null) {
        return "";
    }

    return String(value).trim();
}

var messageControlId =
    valueOf("oru_message_control_id");

var messageType =
    valueOf("oru_message_type");

var triggerEvent =
    valueOf("oru_trigger_event");

var messageStructure =
    valueOf("oru_message_structure");

var patientIdentifier =
    valueOf("oru_patient_identifier");

var assigningAuthority =
    valueOf("oru_assigning_authority");

var identifierType =
    valueOf("oru_identifier_type");

var placerOrderNumber =
    valueOf("oru_placer_order_number");

var fillerOrderNumber =
    valueOf("oru_filler_order_number");

var serviceCode =
    valueOf("oru_service_code");

var serviceCodingSystem =
    valueOf("oru_service_coding_system");

var obrStatus =
    valueOf("oru_obr_status");

var obxValueType =
    valueOf("oru_obx_value_type");

var observationCode =
    valueOf("oru_observation_code");

var observationCodingSystem =
    valueOf("oru_observation_coding_system");

var observationValue =
    valueOf("oru_observation_value");

var units =
    valueOf("oru_units");

var referenceRange =
    valueOf("oru_reference_range");

var abnormalFlag =
    valueOf("oru_abnormal_flag");

var obxStatus =
    valueOf("oru_obx_status");


if (!messageControlId) {
    failures.push("Message control ID present");
}

if (messageType != "ORU") {
    failures.push("Message type is ORU");
}

if (triggerEvent != "R01") {
    failures.push("Trigger event is R01");
}

if (messageStructure != "ORU_R01") {
    failures.push("Message structure is ORU_R01");
}

if (!patientIdentifier) {
    failures.push("Patient ID present");
}

if (!assigningAuthority) {
    failures.push("Assigning authority present");
}

if (identifierType != "MR") {
    failures.push("Identifier type is MR");
}

if (!placerOrderNumber) {
    failures.push("Placer order number present");
}

if (!fillerOrderNumber) {
    failures.push("Filler order number present");
}

if (!serviceCode) {
    failures.push("OBR service code present");
}

if (serviceCodingSystem != "LN") {
    failures.push("OBR coding system is LOINC");
}

if (
    obrStatus != "F" &&
    obrStatus != "P" &&
    obrStatus != "C" &&
    obrStatus != "I" &&
    obrStatus != "X"
) {
    failures.push("OBR result status recognized");
}

if (
    obxValueType != "NM" &&
    obxValueType != "ST" &&
    obxValueType != "TX" &&
    obxValueType != "CE" &&
    obxValueType != "CWE"
) {
    failures.push("OBX value type recognized");
}

if (!observationCode) {
    failures.push("OBX observation code present");
}

if (observationCodingSystem != "LN") {
    failures.push("OBX coding system is LOINC");
}

if (!observationValue) {
    failures.push("OBX observation value present");
}

if (
    obxValueType == "NM" &&
    isNaN(Number(observationValue))
) {
    failures.push(
        "Numeric OBX contains numeric value"
    );
}

if (!units) {
    failures.push("OBX units present");
}

if (!referenceRange) {
    failures.push("OBX reference range present");
}

if (
    abnormalFlag != "H" &&
    abnormalFlag != "L" &&
    abnormalFlag != "HH" &&
    abnormalFlag != "LL" &&
    abnormalFlag != "N"
) {
    failures.push(
        "OBX abnormal flag recognized"
    );
}

if (
    obxStatus != "F" &&
    obxStatus != "P" &&
    obxStatus != "C" &&
    obxStatus != "I" &&
    obxStatus != "X"
) {
    failures.push(
        "OBX result status recognized"
    );
}

if (serviceCode != observationCode) {
    failures.push(
        "OBR and OBX observation codes agree"
    );
}

if (obrStatus != obxStatus) {
    failures.push(
        "OBR and OBX result status agree"
    );
}

var validationStatus =
    failures.length == 0
        ? "PASS"
        : "FAIL";

var failureReason =
    failures.join(" | ");

channelMap.put(
    "oru_validation_status",
    validationStatus
);

channelMap.put(
    "oru_validation_failure_category",
    failures.length == 0
        ? ""
        : "VALIDATION_ERROR"
);

channelMap.put(
    "oru_validation_failure_reason",
    failureReason
);

logger.info(
    "ORU validation: " +
    "status=" + validationStatus +
    ", control_id=" + messageControlId +
    ", failed_rule_count=" +
    failures.length +
    (
        failures.length > 0
            ? ", failed_rules=" + failureReason
            : ""
    )
);

properties.query:
/*
 * ORU_R01_IN
 * Successful ORU persistence
 *
 * Persist one ORU message record and one observation
 * record for the current simplified single-OBX profile.
 *
 * Future work will extend this to repeating OBX segments.
 */

var dbConn = null;

try {

    var dbUrl =
        java.lang.System.getenv(
            "INTEROP_DB_URL"
        );

    var dbUser =
        java.lang.System.getenv(
            "INTEROP_DB_USER"
        );

    var dbPassword =
        java.lang.System.getenv(
            "INTEROP_DB_PASSWORD"
        );

    if (
        dbUrl == null ||
        dbUser == null ||
        dbPassword == null
    ) {
        throw new Error(
            "Required INTEROP_DB_* environment configuration is missing."
        );
    }

    /*
     * Only persist messages that passed semantic validation.
     */
    var validationStatus =
        String(
            channelMap.get(
                "oru_validation_status"
            )
        );

    if (validationStatus != "PASS") {
        return;
    }

    dbConn =
        DatabaseConnectionFactory
            .createDatabaseConnection(
                "org.postgresql.Driver",
                dbUrl,
                dbUser,
                dbPassword
            );

    var insertMessageSql =
        "INSERT INTO audit.oru_messages (" +
        "message_control_id, " +
        "patient_identifier, " +
        "assigning_authority, " +
        "identifier_type, " +
        "placer_order_number, " +
        "filler_order_number, " +
        "sending_application, " +
        "sending_facility, " +
        "message_type, " +
        "trigger_event, " +
        "service_code, " +
        "service_text, " +
        "service_coding_system, " +
        "obr_result_status, " +
        "processing_status" +
        ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) " +
        "RETURNING oru_message_id";

    var result =
        dbConn.executeCachedQuery(
            insertMessageSql,
            [
                String(
                    channelMap.get(
                        "oru_message_control_id"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_patient_identifier"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_assigning_authority"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_identifier_type"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_placer_order_number"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_filler_order_number"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_sending_application"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_sending_facility"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_message_type"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_trigger_event"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_service_code"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_service_text"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_service_coding_system"
                    )
                ),
                String(
                    channelMap.get(
                        "oru_obr_status"
                    )
                ),
                "ACCEPTED"
            ]
        );

    if (!result.next()) {
        throw new Error(
            "ORU message insert did not return oru_message_id."
        );
    }

    var oruMessageId =
        result.getLong(
            "oru_message_id"
        );

    var insertObservationSql =
        "INSERT INTO audit.oru_observations (" +
        "oru_message_id, " +
        "observation_code, " +
        "observation_text, " +
        "observation_coding_system, " +
        "value_type, " +
        "observation_value, " +
        "units, " +
        "reference_range, " +
        "abnormal_flag, " +
        "result_status" +
        ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

    dbConn.executeUpdate(
        insertObservationSql,
        [
            oruMessageId,
            String(
                channelMap.get(
                    "oru_observation_code"
                )
            ),
            String(
                channelMap.get(
                    "oru_observation_text"
                )
            ),
            String(
                channelMap.get(
                    "oru_observation_coding_system"
                )
            ),
            String(
                channelMap.get(
                    "oru_obx_value_type"
                )
            ),
            String(
                channelMap.get(
                    "oru_observation_value"
                )
            ),
            String(
                channelMap.get(
                    "oru_units"
                )
            ),
            String(
                channelMap.get(
                    "oru_reference_range"
                )
            ),
            String(
                channelMap.get(
                    "oru_abnormal_flag"
                )
            ),
            String(
                channelMap.get(
                    "oru_obx_status"
                )
            )
        ]
    );

    logger.info(
        "ORU persistence: " +
        "control_id=" +
        channelMap.get(
            "oru_message_control_id"
        ) +
        ", oru_message_id=" +
        oruMessageId +
        ", observation=" +
        channelMap.get(
            "oru_observation_code"
        )
    );

}
finally {

    if (dbConn != null) {
        dbConn.close();
    }
}

var dbConn = null;

try {

    var dbUrl =
        java.lang.System.getenv("INTEROP_DB_URL");

    var dbUser =
        java.lang.System.getenv("INTEROP_DB_USER");

    var dbPassword =
        java.lang.System.getenv("INTEROP_DB_PASSWORD");

    if (
        dbUrl == null ||
        dbUser == null ||
        dbPassword == null
    ) {
        throw new Error(
            "Required INTEROP_DB_* environment configuration is missing."
        );
    }

    dbConn =
        DatabaseConnectionFactory
            .createDatabaseConnection(
                "org.postgresql.Driver",
                dbUrl,
                dbUser,
                dbPassword
            );

    var rawPayload =
        String(
            connectorMessage.getRawData()
        );

    var digest =
        java.security.MessageDigest
            .getInstance("SHA-256");

    var hashBytes =
        digest.digest(
            new java.lang.String(
                rawPayload
            ).getBytes("UTF-8")
        );

    var payloadSha256 =
        java.lang.StringBuilder();

    for (
        var i = 0;
        i < hashBytes.length;
        i++
    ) {

        var hex =
            java.lang.Integer
                .toHexString(
                    (hashBytes[i] & 0xff) | 0x100
                )
                .substring(1);

        payloadSha256.append(hex);
    }

    var sql =
        "INSERT INTO audit.quarantined_messages (" +
        "message_control_id, " +
        "message_type, " +
        "trigger_event, " +
        "patient_identifier, " +
        "sending_application, " +
        "sending_facility, " +
        "failure_category, " +
        "failure_reason, " +
        "payload_text, " +
        "payload_sha256" +
        ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

    var parameters =
        new java.util.ArrayList();

    parameters.add(
        channelMap.get(
            "oru_message_control_id"
        )
    );

    parameters.add(
        channelMap.get(
            "oru_message_type"
        )
    );

    parameters.add(
        channelMap.get(
            "oru_trigger_event"
        )
    );

    parameters.add(
        channelMap.get(
            "oru_patient_identifier"
        )
    );

    parameters.add(
        channelMap.get(
            "oru_sending_application"
        )
    );

    parameters.add(
        channelMap.get(
            "oru_sending_facility"
        )
    );

    parameters.add(
        "VALIDATION_ERROR"
    );

    parameters.add(
        channelMap.get(
            "oru_validation_failure_reason"
        )
    );

    parameters.add(
        rawPayload
    );

    parameters.add(
        String(payloadSha256)
    );

    dbConn.executeUpdate(
        sql,
        parameters
    );

    logger.info(
        "ORU quarantine persistence: " +
        "control_id=" +
        channelMap.get(
            "oru_message_control_id"
        ) +
        ", status=QUARANTINED"
    );

}
catch (e) {

    logger.error(
        "ORU quarantine persistence failed: " +
        e
    );

    throw e;
}
finally {

    if (dbConn != null) {
        dbConn.close();
    }
}

channel.postprocessingScript:
/*
 * ORU_R01_IN postprocessor
 *
 * Translate ORU validation state into the
 * application-level HL7 acknowledgment.
 *
 * Policy:
 *
 * validation PASS -> AA
 * validation FAIL -> AR
 * processing error -> AE
 */

var validationStatus =
    channelMap.get("oru_validation_status");

var validationFailureReason =
    channelMap.get(
        "oru_validation_failure_reason"
    );

var connectorMessages =
    message.getConnectorMessages();

var destinationError = false;

var iterator =
    connectorMessages.entrySet().iterator();

while (iterator.hasNext()) {

    var entry = iterator.next();

    var metadataId =
        String(entry.getKey());

    if (metadataId != "0") {

        var status =
            String(
                entry.getValue().getStatus()
            );

        if (status == "ERROR") {
            destinationError = true;
            break;
        }
    }
}


/*
 * Read original source message.
 */

var sourceConnectorMessage =
    connectorMessages.get(0);

var rawMessage =
    String(
        sourceConnectorMessage.getRawData()
    );

var rawSegments =
    rawMessage.split(/\r\n|\n|\r/);

var mshSegment = null;

for (
    var i = 0;
    i < rawSegments.length;
    i++
) {

    if (
        rawSegments[i].indexOf("MSH|")
        == 0
    ) {
        mshSegment = rawSegments[i];
        break;
    }
}

var mshFields =
    mshSegment != null
        ? mshSegment.split("|")
        : [];


/*
 * Recover original sender/receiver context.
 */

var encodingCharacters =
    mshFields.length > 1
        ? mshFields[1]
        : "^~\\&";

var originalSendingApplication =
    mshFields.length > 2
        ? mshFields[2]
        : "LABSYSTEM";

var originalSendingFacility =
    mshFields.length > 3
        ? mshFields[3]
        : "INTEROPLAB";

var originalReceivingApplication =
    mshFields.length > 4
        ? mshFields[4]
        : "MIRTH";

var originalReceivingFacility =
    mshFields.length > 5
        ? mshFields[5]
        : "INTEROPLAB";

var originalControlId =
    mshFields.length > 9
        ? mshFields[9]
        : String(
            channelMap.get(
                "oru_message_control_id"
            )
        );

var processingId =
    mshFields.length > 10
        ? mshFields[10]
        : "P";

var versionId =
    mshFields.length > 11
        ? mshFields[11]
        : "2.5.1";


/*
 * Determine ACK policy.
 */

var ackCode;
var ackText;

if (validationStatus == "FAIL") {

    ackCode = "AR";

    ackText =
        "Message rejected: " +
        (
            validationFailureReason
                ? String(
                    validationFailureReason
                )
                : "ORU validation failed."
        );

}
else if (destinationError) {

    ackCode = "AE";

    ackText =
        "Message processing error.";

}
else if (validationStatus == "PASS") {

    ackCode = "AA";

    ackText =
        "Message accepted.";

}
else {

    ackCode = "AE";

    ackText =
        "Unable to determine ORU validation state.";
}


/*
 * Build ACK.
 */

var ackUuid =
    String(
        java.util.UUID.randomUUID()
    )
    .replace(/-/g, "")
    .substring(0, 16);

var ackControlId =
    "ACK" + ackUuid;

var timestamp =
    new java.text.SimpleDateFormat(
        "yyyyMMddHHmmss.SSS"
    ).format(
        new java.util.Date()
    );

var ack =
    "MSH|" +
    encodingCharacters +
    "|" +
    originalReceivingApplication +
    "|" +
    originalReceivingFacility +
    "|" +
    originalSendingApplication +
    "|" +
    originalSendingFacility +
    "|" +
    timestamp +
    "||" +
    "ACK^R01^ACK|" +
    ackControlId +
    "|" +
    processingId +
    "|" +
    versionId +
    "\r" +

    "MSA|" +
    ackCode +
    "|" +
    originalControlId +
    "|" +
    ackText +
    "\r";


logger.info(
    "ORU postprocessor ACK policy: " +
    "validation_status=" +
    validationStatus +
    ", destination_error=" +
    destinationError +
    ", ack_code=" +
    ackCode +
    ", original_control_id=" +
    originalControlId
);

return ack;

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;
